insert into phase_note (id, position, name, status, detail) values ('F7', 4, 'i18n', 'Publicado', 'Idioma na URL. Interface no dicionário. Textos institucionais via MyMemory, com consentimento.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F8', 5, 'SEO', 'Publicado', 'Canonical, hreflang e dado-LD por calculadora.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F9', 6, 'LGPD', 'Publicado', 'Cookies necessários, tradução e desempenho separados. Paciente não é gravado.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F10', 7, 'Documentos', 'Publicado', 'Folha A4 e DOCX gerado no navegador.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F11', 8, 'Performance', 'Publicado', 'LCP, INP e CLS só com consentimento de medição.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F12', 9, 'Contrato', 'Publicado', 'Cada ferramenta tem texto, entrada e referência. Há robots.txt e sitemap.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F15', 10, 'Institucional', 'Publicado', 'Sobre, políticas, mapa, contato e compromisso no mesmo menu.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F16', 11, 'Conteúdo', 'Publicado', 'Glossário e índice NANDA só do que as escalas já sugerem.') on conflict (id) do nothing;
