insert into phase_note (id, position, name, status, detail) values ('F13', 13, 'Conta', 'Publicado', 'Entrada, assinante e administrador em telas separadas. A fonte publicada governa o que abre.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F14', 14, 'Assinatura', 'Publicado', 'Pedido sem cartão. O administrador ativa. As calculadoras públicas não dependem disso.') on conflict (id) do nothing;
insert into phase_note (id, position, name, status, detail) values ('F18', 15, 'Comunidade', 'Publicado', 'Quadro de recados para assinatura ativa. O administrador pode ocultar.') on conflict (id) do nothing;
