insert into inst_page (path, title, kicker, lead, kind) values ('acessibilidade/declaracao-de-acessibilidade', 'Declaração de Acessibilidade', 'Central de Acessibilidade Digital', 'Nosso compromisso com a acessibilidade digital: o padrão que seguimos, os recursos disponíveis, como navegar pelo teclado e como reportar barreiras.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('acessibilidade/declaracao-de-acessibilidade', 1, '1. Nosso compromisso', 'Queremos que todas as pessoas consigam usar as calculadoras e conteúdos, inclusive com tecnologias assistivas. Adotamos como referência as Diretrizes de Acessibilidade para Conteúdo Web (WCAG) 2.2, nível AA , com atenção a contraste, navegação por teclado, foco visível, nomes acessíveis, estrutura semântica e compatibi') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('acessibilidade/declaracao-de-acessibilidade', 2, '2. Recursos disponíveis', 'Ajuste de tamanho de fonte, inversão de contraste e espaçamento de texto.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('acessibilidade/declaracao-de-acessibilidade', 3, '3. Navegação pelo teclado', '') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('acessibilidade/declaracao-de-acessibilidade', 4, '4. Leitores de tela', 'Buscamos compatibilidade com os leitores de tela mais usados:') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('acessibilidade/declaracao-de-acessibilidade', 5, '5. Limitações conhecidas', 'PENDENTE: listar as limitações conhecidas e o prazo previsto para cada correção.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('acessibilidade/declaracao-de-acessibilidade', 6, '6. Encontrou uma barreira?', 'A acessibilidade é um trabalho contínuo. Se algo impedir você de usar uma calculadora ou conteúdo, escreva para ciadeenfermagem@gmail.com informando a página, o problema e, se possível, o navegador e a tecnologia assistiva usados. Analisamos e corrigimos com prioridade. Prazo de resposta: PENDENTE.') on conflict (path, position) do nothing;
insert into inst_page (path, title, kicker, lead, kind) values ('acessibilidade', 'Central de Acessibilidade Digital', 'Centrais institucionais', 'Nível de conformidade, recursos disponíveis e como reportar barreiras.', 'hub') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('acessibilidade', 1, 'Declaração de Acessibilidade', 'Nosso compromisso com a acessibilidade digital: o padrão que seguimos, os recursos disponíveis, como navegar pelo teclado e como reportar barreiras.') on conflict (path, position) do nothing;
