insert into inst_page (path, title, kicker, lead, kind) values ('assinante/cancelamento-e-reembolso', 'Cancelamento e reembolso', 'Central do Assinante', 'Como cancelar a assinatura Premium, quando você tem direito a reembolso e em quanto tempo o valor volta.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/cancelamento-e-reembolso', 1, '1. Direito de arrependimento: 7 dias', 'Ao assinar o Premium pela primeira vez, você pode desistir em até 7 (sete) dias a contar da contratação, sem precisar justificar. O reembolso observará esta política e a legislação aplicável. Eventuais taxas de processamento serão tratadas conforme as condições vigentes do meio de pagamento e a legislação aplicável.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/cancelamento-e-reembolso', 2, '2. Reembolso em renovações', '') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/cancelamento-e-reembolso', 3, '3. Como pedir cancelamento ou reembolso', 'Informe o e-mail da conta e se o pedido é de cancelamento, reembolso ou ambos.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/cancelamento-e-reembolso', 4, '4. Cancelamento da assinatura', '') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/cancelamento-e-reembolso', 5, '5. Prazos de devolução', '') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/cancelamento-e-reembolso', 6, '6. Mudanças nesta política', 'Mudanças nesta política serão comunicadas aos assinantes por e-mail com antecedência de PENDENTE dias. Ao assinar, você declara ter lido esta política e os Termos de Uso .') on conflict (path, position) do nothing;
insert into inst_page (path, title, kicker, lead, kind) values ('assinante/condicoes-da-assinatura', 'Condições da assinatura Premium', 'Central do Assinante', 'Como funciona a cobrança, a renovação, os reajustes e a liberação do acesso Premium.', 'page') on conflict (path) do nothing;
