insert into inst_page (path, title, kicker, lead, kind) values ('assinante/termos-de-uso', 'Termos de Uso', 'Central do Assinante', 'As regras para usar o site, suas ferramentas e conteúdos, nas modalidades gratuita e Premium.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/termos-de-uso', 1, '1. Definições', '') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/termos-de-uso', 2, '2. O que estes termos regulam', 'Estes Termos regulam o uso do site e de suas ferramentas, conteúdos e serviços, sempre com caráter informativo, educativo e consultivo, em duas modalidades:') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/termos-de-uso', 3, '3. Público e uso adequado', 'A plataforma é voltada a profissionais e estudantes da área da saúde. As ferramentas não são indicadas para autodiagnóstico pelo público leigo. Os limites de uso clínico estão no Aviso clínico , que faz parte destes Termos.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/termos-de-uso', 4, '4. Compromissos do usuário', '') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/termos-de-uso', 5, '5. Limites de uso', 'Os resultados são apoio educativo e conferência comparativa ao raciocínio clínico e não substituem a decisão profissional presencial e fundamentada. Não respondemos por decisões tomadas sem a validação profissional prevista no Aviso clínico , sem prejuízo dos direitos garantidos pela legislação de defesa do consumidor.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('assinante/termos-de-uso', 6, '6. Propriedade intelectual', 'Código-fonte, identidade visual, textos, logotipos, scripts e bases lógicas das calculadoras desenvolvidos pela equipe pertencem à Cia de Enfermagem e são protegidos pela Lei de Direitos Autorais (Lei nº 9.610/98) e pela legislação de propriedade industrial.') on conflict (path, position) do nothing;
insert into inst_page (path, title, kicker, lead, kind) values ('editorial/auditoria-governanca-regulatoria', 'Auditoria de Governança Regulatória', 'Central Editorial', 'Método interno e periódico para verificar se conteúdos regulatórios, éticos, legais e clínicos têm fontes verificáveis, evidência adequada, classificação de risco e transparência editorial.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/auditoria-governanca-regulatoria', 1, '1. O que é a Auditoria de Governança Regulatória', 'É o método interno adotado pelo Calculadoras de Enfermagem para verificar, de forma sistemática, se conteúdos regulatórios, éticos, legais e clínicos apresentam fontes verificáveis, evidências adequadas, classificação de risco e transparência editorial .') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/auditoria-governanca-regulatoria', 2, '2. Periodicidade: duas auditorias ordinárias por ano', 'O método integra o ciclo permanente de governança editorial, com duas auditorias ordinárias por ano , para detectar alterações de vigência, mudanças regulatórias, referências desatualizadas, problemas de atribuição e divergências entre o conteúdo e suas fontes.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/auditoria-governanca-regulatoria', 3, '3. Classificação de risco: HIGH, MEDIUM e LOW', 'Conteúdo normativo, regulatório, clínico ou legal cuja exatidão pode afetar interpretação profissional, conduta, direitos, deveres ou conformidade.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/auditoria-governanca-regulatoria', 4, '4. Justiça nas fontes', '“Justiça nas fontes” significa tratar cada referência de forma proporcional ao que ela realmente demonstra. Uma fonte não deve sustentar uma conclusão mais ampla do que seu próprio conteúdo permite.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/auditoria-governanca-regulatoria', 5, '5. Respeito aos autores e às fontes', 'A atribuição correta é parte da qualidade da informação. Autores, instituições, órgãos reguladores e documentos oficiais são identificados de maneira compatível com a fonte utilizada.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/auditoria-governanca-regulatoria', 6, '6. Uma governança voltada à prática de enfermagem', 'A plataforma é dedicada a profissionais de enfermagem : escalas, calculadoras, conteúdos clínicos e materiais de apoio à prática assistencial. Por isso, qualidade da informação não é só questão de redação ou de apresentação visual.') on conflict (path, position) do nothing;
insert into inst_page (path, title, kicker, lead, kind) values ('editorial/aviso-clinico', 'Aviso clínico e limites de uso', 'Central Editorial', 'As calculadoras e escalas são apoio educativo e comparativo ao raciocínio clínico. Não substituem a avaliação, o julgamento nem a responsabilidade técnica do profissional.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/aviso-clinico', 1, '1. Natureza das ferramentas', 'Os resultados das calculadoras e escalas se baseiam em fórmulas consagradas, literatura validada e protocolos amplamente aceitos. Mesmo assim, devem ser interpretados como apoio educativo ou conferência comparativa ao raciocínio clínico, nunca como decisão.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/aviso-clinico', 2, '2. Para quem as ferramentas são destinadas', 'As ferramentas são voltadas a profissionais e estudantes da área da saúde . Não são indicadas para autodiagnóstico pelo público leigo: o uso adequado exige conhecimento técnico, anatômico e farmacológico prévio para interpretar e aplicar os resultados.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/aviso-clinico', 3, '3. O que cabe a quem usa', 'Em caso de dúvida sobre a formulação ou o resultado de um cálculo, procure seu professor de enfermagem ou o enfermeiro responsável, habilitados para orientar o procedimento correto.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/aviso-clinico', 4, '4. O que fazemos do nosso lado', 'Cada ferramenta passa pelo fluxo descrito em Uso responsável de inteligência artificial e pela Auditoria de Governança Regulatória . Erros relatados são analisados e corrigidos.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/aviso-clinico', 5, 'Nota de transparência', 'Esta página descreve políticas e práticas institucionais do Calculadoras de Enfermagem. Ferramentas de IA podem apoiar pesquisa, organização e conferência do texto, mas não constituem autoridade científica ou regulatória e não substituem a revisão humana, a competência profissional nem as fontes oficiais.') on conflict (path, position) do nothing;
insert into inst_page (path, title, kicker, lead, kind) values ('editorial/correcoes-e-erratas', 'Correções e erratas', 'Central Editorial', 'Como reportar um erro, como tratamos cada relato conforme o risco e onde as correções ficam registradas.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/correcoes-e-erratas', 1, '1. Como reportar', 'Escreva para ciadeenfermagem@gmail.com ou use o formulário informando:') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/correcoes-e-erratas', 2, '2. Como tratamos cada relato', 'O relato é registrado e classificado por risco.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/correcoes-e-erratas', 3, '3. Registro de erratas', 'Correções de risco HIGH e MEDIUM ficam listadas aqui, além do histórico de cada página.') on conflict (path, position) do nothing;
