insert into inst_section (path, position, title, body) values ('editorial/fontes-e-evidencias', 4, '4. Quando as fontes divergem', '') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/fontes-e-evidencias', 5, '5. Como citamos', 'Toda página com conteúdo técnico tem a seção "Referências e fontes", com autor ou órgão, título, número e data do documento e link para a fonte oficial quando houver.') on conflict (path, position) do nothing;
