insert into inst_page (path, title, kicker, lead, kind) values ('editorial', 'Central Editorial', 'Centrais institucionais', 'Como o conteúdo é produzido, verificado, auditado e corrigido — e os limites do seu uso clínico.', 'hub') on conflict (path) do nothing;
