insert into inst_page (path, title, kicker, lead, kind) values ('editorial/politica-editorial', 'Política editorial', 'Central Editorial', 'Os princípios que orientam o que publicamos, como escolhemos fontes, quem revisa, como atualizamos e como mantemos a independência do conteúdo.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/politica-editorial', 1, '1. Princípios', 'Publicamos o que fontes oficiais, científicas e normativas sustentam, na medida do que elas demonstram.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/politica-editorial', 2, '2. O que publicamos', 'Calculadoras, escalas, guias, simulados, artigos e conteúdos regulatórios voltados a profissionais e estudantes de enfermagem, sempre com caráter educativo e de apoio. Os limites de uso estão no Aviso clínico .') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/politica-editorial', 3, '3. Fontes', 'Os critérios de aceitação e a hierarquia de fontes estão em Fontes e evidências . Nenhuma fonte recebe tratamento privilegiado só por ser citada.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/politica-editorial', 4, '4. Classificação por risco', '') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/politica-editorial', 5, '5. Atualização', 'O conteúdo passa por duas auditorias ordinárias por ano e por auditoria extraordinária quando muda uma norma, uma diretriz ou quando uma fonte é contestada. Cada página mostra data de atualização, versão e histórico.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/politica-editorial', 6, '6. Independência editorial', 'Anúncios e assinaturas financiam a plataforma, mas não definem o conteúdo clínico. Anunciantes não escolhem, revisam nem aprovam o que publicamos.') on conflict (path, position) do nothing;
insert into inst_page (path, title, kicker, lead, kind) values ('editorial/uso-responsavel-de-ia', 'Uso responsável de inteligência artificial', 'Central Editorial', 'Como produzimos, validamos e auditamos cada conteúdo: fontes oficiais como base, tripla checagem por IA, governança reforçada para conteúdo de alto risco e revisão final de enfermeiro habilitado.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/uso-responsavel-de-ia', 1, '1. Nosso método de trabalho', 'Todo conteúdo publicado (calculadoras, escalas, guias, simulados, artigos e formulários) passa por um fluxo editorial estruturado . A inteligência artificial apoia a organização, a comparação e a identificação de inconsistências, mas não é a fonte do conteúdo : as fontes oficiais, científicas e normativas continuam sen') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/uso-responsavel-de-ia', 2, '2. Governança de conteúdo de alto risco', 'Nem todo conteúdo tem o mesmo peso. Mantemos uma biblioteca de governança de conteúdo de alto risco , que classifica páginas, ferramentas e documentos pelo potencial de impacto clínico, regulatório e educacional.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/uso-responsavel-de-ia', 3, '3. Tripla checagem por IA', 'São três camadas independentes , executadas em momentos e com propósitos distintos. Um erro precisa passar por três verificações diferentes para chegar à publicação.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('editorial/uso-responsavel-de-ia', 4, '4. A revisão do enfermeiro', 'A automação termina antes da decisão final. Antes da publicação, páginas, documentos, artigos, calculadoras e escalas passam por revisão editorial de profissional de enfermagem habilitado e em atividade , registrada no fluxo interno.') on conflict (path, position) do nothing;
