insert into inst_section (path, position, title, body) values ('privacidade/politica-de-privacidade', 1, '1. Em resumo', 'Não exigimos cadastro para usar as calculadoras. Os dados clínicos digitados são processados no seu navegador e não são enviados aos nossos servidores.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('privacidade/politica-de-privacidade', 2, '2. Quem é responsável pelos seus dados', 'Esta política se aplica ao site Calculadoras de Enfermagem. Para assuntos de privacidade e exercício de direitos, utilize o canal oficial abaixo.') on conflict (path, position) do nothing;
