insert into inst_section (path, position, title, body) values ('privacidade/politica-de-privacidade', 5, '5. Publicidade e Google AdSense', 'Exibimos anúncios para financiar a manutenção do site, inclusive para assinantes Premium. Por isso, o Google e outros parceiros podem ler e gravar cookies ou usar web beacons no seu navegador para veicular anúncios com base em visitas anteriores e para medir resultados.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('privacidade/politica-de-privacidade', 6, '6. Compartilhamento e transferência internacional', 'Compartilhamos dados apenas com os fornecedores de tecnologia necessários para operar o site, listados na tabela acima.') on conflict (path, position) do nothing;
