insert into inst_section (path, position, title, body) values ('sobre/equipe-e-autores', 1, '1. Quem responde pelo conteúdo', 'Responsável técnico de enfermagem · formação: PENDENTE · COREN-UF PENDENTE') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/equipe-e-autores', 2, '2. Como os papéis se dividem', 'Os detalhes do fluxo estão em Uso responsável de inteligência artificial e na Auditoria de Governança Regulatória .') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/equipe-e-autores', 3, '3. Conflitos de interesse', 'PENDENTE: declarar vínculos que possam influenciar o conteúdo, ou que não há vínculos.') on conflict (path, position) do nothing;
