insert into inst_page (path, title, kicker, lead, kind) values ('sobre/missao-visao-valores', 'Missão, Visão e Valores', 'Central Institucional', 'Por que a plataforma existe, aonde queremos chegar e os princípios que orientam cada calculadora, escala e conteúdo publicado.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/missao-visao-valores', 1, '1. Quem somos', 'Nascemos da necessidade de oferecer aos profissionais de enfermagem uma base tecnológica confiável, rápida e de fácil acesso. O portal reúne escalas, scores de avaliação e cálculos de gotejamento e dosagem, reduzindo o tempo administrativo e o risco de erro na assistência.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/missao-visao-valores', 2, '2. Missão e visão', 'Disponibilizar calculadoras e ferramentas de apoio clínico precisas e acessíveis, para otimizar o tempo e promover a segurança nas decisões e condutas da enfermagem.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/missao-visao-valores', 3, '3. Valores', 'Foco absoluto na segurança do paciente.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/missao-visao-valores', 4, 'Nota de transparência', 'Esta página descreve políticas e práticas institucionais do Calculadoras de Enfermagem. Ferramentas de IA podem apoiar pesquisa, organização e conferência do texto, mas não constituem autoridade científica ou regulatória e não substituem a revisão humana, a competência profissional nem as fontes oficiais.') on conflict (path, position) do nothing;
insert into inst_page (path, title, kicker, lead, kind) values ('sobre/objetivos-do-site', 'Objetivos do site', 'Central Institucional', 'O que a plataforma busca oferecer a profissionais e estudantes de enfermagem, com foco em apoio ao estudo, à prática, à gestão e ao uso responsável das ferramentas.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/objetivos-do-site', 1, '1. O que oferecemos', 'Oferecemos a profissionais e estudantes de enfermagem ferramentas práticas para o cálculo de medicamentos e doses , a partir de prescrições, simulações ou questões de cursos: o usuário informa os dados solicitados e a calculadora aplica as fórmulas necessárias.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/objetivos-do-site', 2, '2. Escalas a serviço da equipe multiprofissional', 'Na maioria das vezes, essas escalas são aplicadas pela equipe de enfermagem e orientam condutas de toda a equipe multiprofissional: técnicos de enfermagem, enfermeiros, médicos e fisioterapeutas. Em algumas, a atuação do enfermeiro é mais ativa; em outras, o instrumento serve de base de monitoramento para a decisão méd') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/objetivos-do-site', 3, '3. Gestão e educação', 'Recursos para apoiar lideranças e instituições: dimensionamento de equipe de enfermagem, Escala de Fugulin (complexidade assistencial), classificação de pacientes de Perroca (SCP) e SBAR para passagem de plantão.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/objetivos-do-site', 4, '4. Apoio, nunca substituição', 'Os cálculos têm caráter consultivo e didático , baseados em referências reconhecidas que devem ser consultadas para validação. Nenhum cálculo automatizado substitui a análise, o julgamento e a responsabilidade técnica do profissional de enfermagem.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sobre/objetivos-do-site', 5, 'Nota de transparência', 'Esta página descreve políticas e práticas institucionais do Calculadoras de Enfermagem. Ferramentas de IA podem apoiar pesquisa, organização e conferência do texto, mas não constituem autoridade científica ou regulatória e não substituem a revisão humana, a competência profissional nem as fontes oficiais.') on conflict (path, position) do nothing;
insert into inst_page (path, title, kicker, lead, kind) values ('sustentabilidade/compromisso-e-praticas', 'Sustentabilidade digital — compromisso e práticas', 'Central de Sustentabilidade Digital', 'Cada página carregada consome energia em servidores, redes e no seu aparelho. Estas são as práticas que adotamos para reduzir esse consumo sem perder qualidade.', 'page') on conflict (path) do nothing;
insert into inst_section (path, position, title, body) values ('sustentabilidade/compromisso-e-praticas', 1, '1. Por que isso importa', 'A internet consome energia em data centers, redes e dispositivos. Páginas mais leves transferem menos dados, exigem menos processamento e gastam menos bateria do seu aparelho. Por isso tratamos desempenho como uma questão ambiental , além de experiência de uso.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sustentabilidade/compromisso-e-praticas', 2, '2. Práticas que adotamos', 'Evitamos bibliotecas pesadas e scripts desnecessários, exigindo menos do processador do seu aparelho.') on conflict (path, position) do nothing;
insert into inst_section (path, position, title, body) values ('sustentabilidade/compromisso-e-praticas', 3, '3. Como acompanhamos', 'Monitoramos o site com ferramentas públicas de desempenho e emissão estimada:') on conflict (path, position) do nothing;
