insert into agent_rule (agent_id, position, body) values ('ui-ux', 1, 'Um único template para escala e calculadora. O que muda é a entrada, não a página.') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('ui-ux', 2, 'Ordem da tela: paciente só na escala, entrada, ações, resultado e memória. NANDA e observação só no laudo.') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('ui-ux', 3, 'Menu: Concurso Santos, Início, Sobre Nós, Calculadoras, Conteúdos, Sites de Emprego, Simulados, Biblioteca, Fale Conosco, Entrar e Assine já.') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('ui-ux', 4, 'Item no ar abre a ferramenta. Item catalogado abre a seção do menu, nunca uma página genérica.') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('ui-ux', 5, 'Marinha #1A3E74, Inter nos textos, foco amarelo, cartão branco. Sem paleta azul-céu/índigo, exceto o botão Assine já.') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('ui-ux', 6, 'Resultado à direita no desktop e logo após as ações no celular. Alvo de toque de pelo menos 44 px.') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('ui-ux', 7, 'Não mostrar escore zero antes do cálculo. Vazio é “aguardando”, não um resultado falso.') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('ui-ux', 8, 'Título de seção usa o token de fonte da página. Conteúdo relacionado usa o mesmo cartão das outras páginas.') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('ui-ux', 9, 'Não publica e não grava a fonte.') on conflict (agent_id, position) do nothing;
