insert into agent_basis (agent_id, position, citation) values ('cx', 3, 'Lei 7.498/1986, art. 11: prescrição de enfermagem não sai de uma calculadora pública') on conflict (agent_id, position) do nothing;
insert into agent_rule (agent_id, position, body) values ('cx', 1, 'Dados do paciente ficam só na tela. Não vão para cookie, localStorage nem para o banco.') on conflict (agent_id, position) do nothing;
